// Security headers on real responses (run against `next build && next start`, like all e2e).
// Generated by `eos scaffold web-security`; yours to edit. Fails if someone drops the CSP or a header.
import { expect, test } from "@playwright/test";

test("home sends a nonce-based CSP and the security headers @smoke", async ({ page }) => {
  const response = await page.goto("/");
  expect(response, "no response for /").not.toBeNull();
  const h = response!.headers();
  const csp = h["content-security-policy"] ?? h["content-security-policy-report-only"] ?? "";
  expect(csp).toMatch(/script-src [^;]*'nonce-[A-Za-z0-9+/=]+'/);
  expect(csp).toContain("'strict-dynamic'");
  expect(csp).toContain("object-src 'none'");
  expect(csp).toContain("frame-ancestors 'none'");
  expect(csp).not.toMatch(/script-src [^;]*'unsafe-inline'/);
  expect(h["x-content-type-options"]).toBe("nosniff");
  expect(h["referrer-policy"]).toBeTruthy();
  expect(h["x-powered-by"], "set poweredByHeader: false in next.config").toBeUndefined();
});

test("the page runs under the CSP without violations", async ({ page }) => {
  const violations: string[] = [];
  page.on("console", (msg) => {
    if (/Content Security Policy|Content-Security-Policy/i.test(msg.text())) violations.push(msg.text());
  });
  await page.goto("/");
  await page.waitForLoadState("networkidle");
  expect(violations).toEqual([]);
});
